<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import TeamPage from './TeamPage.vue'
import { BookOpen, LayoutDashboard, CalendarDays, GraduationCap, Users, CreditCard, ScrollText, Settings2, LogOut, ArrowUpRight, ArrowRight, Plus, Search, Check, X, LoaderCircle, RefreshCw, ShieldCheck, ChevronRight, Menu, AlertCircle } from 'lucide-vue-next'
const showTeam=ref(window.location.hash==='#team')
function syncPublicPage(){showTeam.value=window.location.hash==='#team';window.scrollTo(0,0)}
onMounted(()=>window.addEventListener('hashchange',syncPublicPage))
onUnmounted(()=>window.removeEventListener('hashchange',syncPublicPage))
const user=ref(null), csrf=ref(''), loading=ref(true), busy=ref(false), tab=ref('overview'), mobile=ref(false)
const error=ref(''), success=ref(''), catalog=ref([]), overview=ref({term:{},stats:{}}), schedule=ref({choices:[],submitted:false})
const primary=ref([]), alternate=ref([]), query=ref(''), department=ref('all'), onlyAvailable=ref(false)
const report=ref({grades:[]}), teaching=ref({eligible:[],mine:[]}), teachIds=ref([]), roster=ref(null)
const users=ref([]), invoices=ref([]), events=ref([]), integrations=ref({catalog_available:true,billing_available:true})
const loginForm=reactive({username:'student01',password:'Demo2026!'})
const userForm=ref(null), eligibilityUser=ref(null), eligibilityIds=ref([]), confirmBox=ref(null)
const roleNames={student:'学生',professor:'教师',registrar:'教务管理员'}
const statuses={selected:'已保存',enrolled:'已选中',cancelled:'已取消',open:'选课中',closed:'已关闭',pending:'待重试',sent:'已发送'}
const weekdays=['','周一','周二','周三','周四','周五','周六','周日']
const termOpen=computed(()=>overview.value.term.state==='open')
const nav=computed(()=>user.value?.role==='student' ? [ ['overview','学习概览',LayoutDashboard],['catalog','课程目录',BookOpen],['schedule','我的课表',CalendarDays],['grades','成绩单',GraduationCap] ] : user.value?.role==='professor' ? [['overview','教学概览',LayoutDashboard],['catalog','课程目录',BookOpen],['teaching','授课安排',BookOpen],['roster','名单与成绩',GraduationCap]] : [['overview','教务概览',LayoutDashboard],['catalog','课程目录',BookOpen],['users','师生管理',Users],['registration','选课管理',CalendarDays],['invoices','计费记录',CreditCard],['audit','操作日志',ScrollText],['integrations','外部服务',Settings2]])
const title=computed(()=>nav.value.find(x=>x[0]===tab.value)?.[1]||'概览')
const filtered=computed(()=>catalog.value.filter(o=>(o.name+o.code+o.professor).toLowerCase().includes(query.value.toLowerCase())&&(!onlyAvailable.value||(o.status==='open'&&o.enrolled<10))&&(department.value==='all'||String(o.day)===department.value)))
const chosen=computed(()=>primary.value.map(id=>catalog.value.find(x=>x.id===id)).filter(Boolean))
const alternatives=computed(()=>alternate.value.map(id=>catalog.value.find(x=>x.id===id)).filter(Boolean))
const uniqueCourses=computed(()=>[...new Map(catalog.value.map(o=>[o.course_id,o])).values()])
const credits=computed(()=>chosen.value.reduce((sum,o)=>sum+o.credits,0))
const ownEnrolled=computed(()=>schedule.value.choices.filter(c=>c.status==='enrolled'))
const historical=computed(()=>teaching.value.mine.filter(o=>o.term_id<overview.value.term.id))
const filteredUsers=computed(()=>users.value.filter(u=>(u.name+u.username).toLowerCase().includes(query.value.toLowerCase())))
const time=o=>`${weekdays[o.day]} · 第 ${o.start}–${o.end} 节`
let timer
async function api(path,method='GET',data) {
 const res=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.value},...(data===undefined?{}:{body:JSON.stringify(data)})})
 const json=await res.json()
 if(!res.ok){if(res.status===401&&path!=='/login'){user.value=null;tab.value='overview'} throw new Error(json.error||'服务请求失败')}
 return json
}
async function act(fn,message='') { if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();success.value=message}catch(e){error.value=e.message}finally{busy.value=false} }
async function sessionLoad(){const s=await api('/session');csrf.value=s.csrf;user.value=s.user}
async function loadCore(){overview.value=await api('/overview');if(user.value.role==='student'){schedule.value=await api('/schedule');loadChoices()} if(user.value.role==='professor'){teaching.value=await api('/teaching');teachIds.value=teaching.value.mine.filter(o=>o.term_id===overview.value.term.id).map(o=>o.id)}}
function loadChoices(){primary.value=schedule.value.choices.filter(c=>c.kind==='primary').sort((a,b)=>a.rank-b.rank).map(c=>c.offering.id);alternate.value=schedule.value.choices.filter(c=>c.kind==='alternate').sort((a,b)=>a.rank-b.rank).map(c=>c.offering.id)}
async function loadCatalog(){catalog.value=(await api('/catalog')).offerings}
async function navigate(next){window.scrollTo(0,0);tab.value=next;query.value='';mobile.value=false;error.value='';success.value='';await act(async()=>{
 if(['overview','catalog','schedule','teaching'].includes(next))await loadCatalog()
 if(next==='grades')report.value=await api('/report-card')
 if(['teaching','roster'].includes(next)){teaching.value=await api('/teaching');teachIds.value=teaching.value.mine.filter(o=>o.term_id===overview.value.term.id).map(o=>o.id)}
 if(next==='users'){users.value=(await api('/users')).users;await loadCatalog()}
 if(next==='invoices')invoices.value=(await api('/invoices')).invoices
 if(next==='audit')events.value=(await api('/audit')).events
 if(next==='integrations')integrations.value=await api('/integrations')
 overview.value=await api('/overview')
 })}
async function login(){await act(async()=>{const s=await api('/login','POST',loginForm);user.value=s.user;csrf.value=s.csrf;tab.value='overview';await loadCore();await loadCatalog()})}
async function logout(){await act(async()=>{await api('/logout','POST',{});user.value=null;roster.value=null;catalog.value=[];await sessionLoad()})}
function quick(role){loginForm.username={student:'student01',professor:'professor01',registrar:'admin'}[role];loginForm.password='Demo2026!'}
function toggle(o,kind){error.value='';success.value='';const target=kind==='primary'?primary:alternate;const other=kind==='primary'?alternate:primary;if(target.value.includes(o.id)){target.value=target.value.filter(id=>id!==o.id);return}if(target.value.length>=(kind==='primary'?4:2)){error.value=kind==='primary'?'最多选择 4 门主选课程':'最多选择 2 门备选课程';return}if([...primary.value,...alternate.value].some(id=>catalog.value.find(x=>x.id===id)?.course_id===o.course_id)){error.value='同一课程不能重复选择，请先取消原来的选择';return}other.value=other.value.filter(id=>id!==o.id);target.value.push(o.id)}
async function saveSchedule(submit){await act(async()=>{schedule.value=await api('/schedule','PUT',{primary:primary.value,alternate:alternate.value,submit});loadChoices();await loadCatalog();overview.value=await api('/overview')},submit?'选课已提交，名额已确认。':'草稿已保存，暂不占用课程名额。')}
function confirm(title,description,action){confirmBox.value={title,description,action}}
async function doConfirm(){const action=confirmBox.value.action;confirmBox.value=null;await action()}
function deleteSchedule(){confirm('删除本学期课表','删除后将释放全部已选课程的名额，此操作需要重新选课。',()=>act(async()=>{await api('/schedule','DELETE');schedule.value={choices:[],submitted:false};loadChoices();await loadCatalog();overview.value=await api('/overview')},'课表已删除。'))}
async function saveTeaching(){await act(async()=>{await api('/teaching','PUT',{offering_ids:teachIds.value});teaching.value=await api('/teaching');await loadCatalog()},'授课安排已保存。')}
async function getRoster(id){if(!id){roster.value=null;return}await act(async()=>{roster.value=await api(`/offerings/${id}/roster`)})}
async function saveGrades(){await act(async()=>{await api(`/offerings/${roster.value.offering.id}/grades`,'PUT',{grades:roster.value.students.map(s=>({student_id:s.id,value:s.grade}))})},'成绩已保存，学生可查看更新后的成绩单。')}
function editUser(u){userForm.value=u?{...u,password:''}:{username:'',name:'',role:'student',department:'计算机科学与技术',status:'active',birth_date:'',graduation_date:'',identity_number:'',password:''}}
async function saveUser(){await act(async()=>{const u=userForm.value;await api('/users'+(u.id?'/'+u.id:''),u.id?'PUT':'POST',u);users.value=(await api('/users')).users;userForm.value=null},'人员信息已保存。')}
function deleteUser(u){confirm('删除人员信息',`确认删除 ${u.name}（${u.username}）？历史成绩会保留，账户将无法登录。`,()=>act(async()=>{await api('/users/'+u.id,'DELETE');users.value=(await api('/users')).users},'人员信息已删除。'))}
async function editEligibility(u){await act(async()=>{eligibilityIds.value=(await api(`/users/${u.id}/eligibility`)).course_ids;eligibilityUser.value=u})}
async function saveEligibility(){await act(async()=>{await api(`/users/${eligibilityUser.value.id}/eligibility`,'PUT',{course_ids:eligibilityIds.value});eligibilityUser.value=null},'授课资格已保存。')}
function closeRegistration(){confirm('确认关闭本学期选课','系统将处理备选补位，取消不足 3 人或没有教师的教学班，并生成计费记录。关闭后学生和教师不能再修改选课安排。',()=>act(async()=>{const result=await api('/registration/close','POST',{confirm:true});overview.value=await api('/overview');success.value=`已关闭选课，取消 ${result.cancelled.length} 个教学班，生成 ${result.invoices} 条计费记录。`}))}
async function saveIntegrations(){await act(async()=>{integrations.value=await api('/integrations','PUT',{catalog_available:integrations.value.catalog_available,billing_available:integrations.value.billing_available})},'模拟服务状态已更新。待发送计费记录会自动重试。')}
onMounted(async()=>{try{await sessionLoad();if(user.value){await loadCore();await loadCatalog()}}catch(e){error.value=e.message}finally{loading.value=false}timer=setInterval(async()=>{if(!user.value||busy.value||document.hidden)return;try{overview.value=await api('/overview');if(['catalog','schedule'].includes(tab.value)){const previous=catalog.value;await loadCatalog();if(primary.value.some(id=>{const old=previous.find(o=>o.id===id),now=catalog.value.find(o=>o.id===id);return old&&now&&old.enrolled<10&&now.enrolled>=10&&!ownEnrolled.value.some(c=>c.offering.id===id)}))error.value='你选择的课程刚刚满员，请调整选择后再提交。'}if(tab.value==='invoices')invoices.value=(await api('/invoices')).invoices}catch(e){error.value=e.message}},15000)})
onUnmounted(()=>clearInterval(timer))
</script>

<template>
 <TeamPage v-if="showTeam" />
 <div v-else-if="loading" class="boot"><LoaderCircle class="spin"/><p>正在连接教务系统…</p></div>
 <main v-else-if="!user" class="login-page">
  <div class="login-entry">
  <section class="login-panel"><div class="login-box"><div class="brand"><span class="brand-mark"><BookOpen/></span><b>知课</b></div><h2>登录课程注册系统</h2><form @submit.prevent="login"><label>账号<input v-model="loginForm.username" autocomplete="username" required placeholder="请输入账号"></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" required placeholder="请输入密码"></label><div v-if="error" class="alert error" role="alert">{{error}}</div><button class="button primary full" :disabled="busy"><LoaderCircle v-if="busy" class="spin"/><span>登录</span><ArrowRight/></button></form><div class="demo-login"><span>课程演示账户</span><div><button @click="quick('student')">学生</button><button @click="quick('professor')">教师</button><button @click="quick('registrar')">教务管理员</button></div><small>选择身份填入演示账号，密码统一为 Demo2026!</small></div></div></section>
  <a href="#team" class="button secondary team-entry"><Users :size="17" />团队说明<ArrowRight :size="16" /></a>
  </div>
 </main>
 <div v-else class="workspace">
  <aside :class="['sidebar',{mobile}]">
   <a class="brand" href="#" @click.prevent="navigate('overview')"><span class="brand-mark"><BookOpen/></span><b>知课<small>课程注册系统</small></b></a>
   <div class="term-label"><span class="tiny">当前学期</span><strong>{{overview.term.name}}</strong><span :class="['badge',termOpen?'green':'gray']"><i/>{{termOpen?'选课进行中':'选课已结束'}}</span></div>
   <div class="nav-label">{{roleNames[user.role]}}工作台</div>
   <nav><button v-for="[key,label,icon] in nav" :key="key" :class="{active:tab===key}" @click="navigate(key)"><component :is="icon" :size="19"/><span>{{label}}</span><ChevronRight v-if="tab===key" :size="15"/></button></nav>
   <div class="sidebar-bottom"><div class="account"><div class="avatar">{{user.name.slice(0,1)}}</div><div><b>{{user.name}}</b><small>{{user.username}}</small></div><button @click="logout" aria-label="退出登录" title="退出登录"><LogOut :size="17"/></button></div></div>
  </aside>
  <div class="main-area"><header class="topbar"><button class="mobile-menu" @click="mobile=!mobile" aria-label="展开导航"><Menu/></button><div>教务服务 <ChevronRight :size="14"/><span>{{title}}</span></div></header>
   <main class="content"><div class="page-heading"><div><h1>{{title}}</h1></div><div class="actions"><button v-if="tab==='overview'" class="button primary compact" @click="navigate(user.role==='student'?'catalog':user.role==='professor'?'teaching':'registration')">{{user.role==='student'?'去选课':user.role==='professor'?'授课安排':'选课管理'}}<ArrowRight :size="15"/></button><button class="button secondary compact" :disabled="busy" @click="navigate(tab)"><RefreshCw :size="15" :class="{spin:busy}"/>刷新</button></div></div>
    <div v-if="error" class="alert error" role="alert"><AlertCircle :size="18"/><span>{{error}}</span><button @click="error=''" aria-label="关闭错误提示"><X :size="16"/></button></div>
    <div v-if="success" class="alert success" role="status"><Check :size="18"/><span>{{success}}</span><button @click="success=''" aria-label="关闭成功提示"><X :size="16"/></button></div>

    <template v-if="tab==='overview'">
     <section class="stat-grid"><article><span>本学期开设</span><strong>{{overview.stats.offerings}}<small>教学班</small></strong></article><article><span>{{user.role==='student'?'我的已选课程':'已确认选课'}}</span><strong>{{user.role==='student'?ownEnrolled.length:overview.stats.enrolled}}<small>{{user.role==='student'?'门':'人次'}}</small></strong></article><article><span>{{user.role==='student'?'当前课表状态':'在校学生账户'}}</span><strong :class="{text:user.role==='student'}">{{user.role==='student'?(schedule.submitted?'已提交':schedule.choices.length?'草稿':'待选课'):overview.stats.students}}<small v-if="user.role!=='student'">人</small></strong></article></section>
     <div class="overview-columns"><section class="panel"><div class="section-heading"><h2>{{user.role==='student'?'我的学习安排':'本学期课程一览'}}</h2><button class="text-button" @click="navigate(user.role==='student'?'schedule':'catalog')">查看全部 <ArrowRight :size="15"/></button></div><template v-if="user.role==='student'&&ownEnrolled.length"><div v-for="c in ownEnrolled" :key="c.offering.id" class="course-row"><div class="course-symbol"><BookOpen :size="21"/></div><div><h3>{{c.offering.name}}</h3><p>{{c.offering.code}} · {{c.offering.professor}} · {{time(c.offering)}}</p></div><span class="badge green">已选中</span></div></template><div v-else-if="user.role==='student'" class="empty"><CalendarDays :size="40" :stroke-width="1.2"/><h3>暂无已确认课程</h3><p>选择 4 门主选、2 门备选，提交后在此查看课表。</p><button class="text-button" @click="navigate('catalog')">去选课 <ArrowRight :size="16"/></button></div><template v-else><div v-for="o in catalog.slice(0,4)" :key="o.id" class="course-row"><div class="course-symbol"><BookOpen :size="20"/></div><div><h3>{{o.name}}</h3><p>{{o.code}} · {{time(o)}}</p></div><span>{{o.enrolled}} / 10 人</span></div></template></section><aside class="guide-panel"><h2>选课规则</h2><ul><li>首次提交需 4 门主选、2 门备选，备选不占名额。</li><li>课程需满足先修要求，且上课时间不冲突。</li><li>每班最多 10 人，选课结束后不足 3 人的班级取消。</li></ul></aside></div>
    </template>

    <template v-if="tab==='catalog'">
     <div class="toolbar"><label class="search"><Search :size="18"/><input v-model="query" placeholder="搜索课程名称、编号或教师" aria-label="搜索课程"></label><select v-model="department" aria-label="上课日期"><option value="all">全部上课时间</option><option v-for="n in 5" :value="String(n)">{{weekdays[n]}}</option></select><label class="check-label"><input type="checkbox" v-model="onlyAvailable">仅看有余量的课程</label></div>
     <div class="catalog-layout"><section><div class="result-line"><span>共 {{filtered.length}} 个教学班</span></div><div class="course-grid"><article v-for="o in filtered" :key="o.id" :class="['course-card',{selected:primary.includes(o.id),alternative:alternate.includes(o.id)}]"><div class="course-card-top"><span class="course-code">{{o.code}} <small>/ {{String(o.id).padStart(2,'0')}} 班</small></span><span :class="['badge',o.status==='cancelled'?'red':o.enrolled>=10?'gray':'green']">{{o.status!=='open'?statuses[o.status]:o.enrolled>=10?'已满员':'可选'}}</span></div><h2>{{o.name}}</h2><p class="course-dept">{{o.department}} · {{o.credits}} 学分</p><div class="course-details"><span><Users :size="15"/>{{o.professor}}</span><span><CalendarDays :size="15"/>{{time(o)}}</span><span><BookOpen :size="15"/>{{o.room}}</span></div><div class="prerequisite">先修要求：{{o.prerequisite_id?uniqueCourses.find(c=>c.course_id===o.prerequisite_id)?.name||'指定先修课程':'无'}}</div><div class="capacity"><div><span>已选 {{o.enrolled}} / 10 人</span></div><div class="meter"><i :style="{width:Math.min(o.enrolled*10,100)+'%'}"/></div></div><div v-if="user.role==='student'" class="course-actions"><button :class="['button',primary.includes(o.id)?'primary':'secondary']" :disabled="!termOpen||busy||o.status!=='open'" @click="toggle(o,'primary')"><Check v-if="primary.includes(o.id)" :size="15"/><Plus v-else :size="15"/>{{primary.includes(o.id)?'已选主选':'加入主选'}}</button><button :class="['button',alternate.includes(o.id)?'alternate-button':'ghost']" :disabled="!termOpen||busy||o.status!=='open'" @click="toggle(o,'alternate')">{{alternate.includes(o.id)?'已选备选':'备选'}}</button></div></article></div><div v-if="!filtered.length" class="empty"><Search :size="35"/><h3>没有匹配的课程</h3><p>试试其他关键词或筛选条件。</p></div></section><aside v-if="user.role==='student'" class="selection-panel"><div class="section-heading"><h2>选课清单</h2><span class="badge gray">{{schedule.submitted?'修改中':'待提交'}}</span></div><p v-if="!schedule.submitted" class="muted small">草稿不保留名额，提交后方可确认。</p><div class="selection-title">主选课程 <b>{{primary.length}} / 4</b></div><div v-for="o in chosen" :key="o.id" class="selection-item"><span><b>{{o.name}}</b><small>{{time(o)}}</small></span><button @click="toggle(o,'primary')" :disabled="!termOpen||busy" :aria-label="'移除主选 '+o.name"><X :size="16"/></button></div><div v-if="!chosen.length" class="selection-empty">从左侧添加你的主选课程</div><div class="selection-title">备选课程（按顺序补位） <b>{{alternate.length}} / 2</b></div><div v-for="(o,i) in alternatives" :key="o.id" class="selection-item"><span><b>{{i+1}}. {{o.name}}</b></span><button @click="toggle(o,'alternate')" :disabled="!termOpen||busy" :aria-label="'移除备选 '+o.name"><X :size="16"/></button></div><div v-if="!alternatives.length" class="selection-empty">添加备选以应对课程取消</div><div class="selection-total"><span>主选合计</span><b>{{credits}} 学分</b></div><button class="button primary full" :disabled="!termOpen||busy" @click="saveSchedule(true)">提交选课 <ArrowRight :size="16"/></button><button class="button secondary full" :disabled="!termOpen||busy||schedule.submitted" @click="saveSchedule(false)">保存草稿</button><small class="selection-note">首次提交需 4 门主选和 2 门备选；已提交后可在选课期内退改选。</small></aside></div>
    </template>

    <template v-if="tab==='schedule'">
     <section class="schedule-summary"><div><span :class="['badge',schedule.submitted?'green':'gray']">{{schedule.submitted?'已提交':'草稿 / 尚未提交'}}</span><h2>{{overview.term.name}}</h2><p>已确认 {{ownEnrolled.length}} 门课程，{{ownEnrolled.reduce((s,c)=>s+c.offering.credits,0)}} 学分。</p></div><div class="actions"><button class="button secondary" :disabled="!termOpen||busy||!schedule.choices.length" @click="deleteSchedule">删除课表</button><button class="button primary" :disabled="!termOpen" @click="navigate('catalog')">调整选课 <ArrowUpRight :size="16"/></button></div></section>
     <section class="panel timetable-panel"><h2>每周课程安排</h2><div class="table-scroll"><table class="timetable"><thead><tr><th>节次</th><th v-for="d in 5">{{weekdays[d]}}</th></tr></thead><tbody><tr v-for="period in [1,3,5,7,9,11]"><th>{{period}}–{{period+1}} 节</th><td v-for="d in 5"><div v-for="c in ownEnrolled.filter(c=>c.offering.day===d&&c.offering.start<=period+1&&c.offering.end>=period)" :key="c.offering.id" class="timetable-course"><b>{{c.offering.name}}</b><small>{{c.offering.room}}</small><small>{{c.offering.professor}}</small></div></td></tr></tbody></table></div><p class="muted small">周课表仅显示已确认课程，不包含草稿和未启用的备选。</p></section>
     <section class="panel"><div class="section-heading"><h2>全部选课记录</h2><span v-if="schedule.choices.some(c=>c.kind==='alternate'&&c.status==='enrolled')" class="muted small">已补位课程仍标记为备选</span></div><div v-if="!schedule.choices.length" class="empty"><p>还没有选课记录。</p></div><div v-for="c in schedule.choices" :key="c.offering.id" class="course-row"><div><h3>{{c.offering.name}}</h3><p>{{c.kind==='primary'?'主选':'备选'}} · {{time(c.offering)}}</p></div><span :class="['badge',c.status==='enrolled'?'green':c.status==='cancelled'?'red':'gray']">{{statuses[c.status]}}</span></div></section>
    </template>

    <template v-if="tab==='grades'"><section class="panel"><div class="section-heading"><div><h2>学期成绩单</h2><p class="muted">{{report.term}} · {{user.name}} · {{user.username}}</p></div><ShieldCheck :size="28" class="green-text"/></div><div class="table-scroll"><table><thead><tr><th>课程编号</th><th>课程名称</th><th>学分</th><th>成绩</th></tr></thead><tbody><tr v-for="g in report.grades" :key="g.code"><td class="mono">{{g.code}}</td><td>{{g.course}}</td><td>{{g.credits}}</td><td><span class="grade">{{g.value}}</span></td></tr></tbody></table></div><div v-if="!report.grades.length" class="empty"><GraduationCap :size="40"/><h3>暂无上学期成绩信息</h3><p>任课教师录入后，成绩会显示在这里。</p></div><p class="footnote">成绩等级为 A、B、C、D、F、I。I 表示课程尚未完成，待录入表示教师尚未提交成绩。</p></section></template>

    <template v-if="tab==='teaching'"><section class="panel"><div class="section-heading"><div><h2>选择本学期授课班级</h2><p class="muted">仅展示具备授课资格的教学班，保存时检查时间冲突。</p></div><button class="button primary" :disabled="busy||!termOpen" @click="saveTeaching">保存授课安排</button></div><div class="table-scroll"><table><thead><tr><th>选择</th><th>课程</th><th>上课时间</th><th>当前教师</th><th>人数</th></tr></thead><tbody><tr v-for="o in teaching.eligible" :key="o.id"><td><input type="checkbox" :value="o.id" v-model="teachIds" :disabled="!termOpen||(o.professor_id&&o.professor_id!==user.id)" :aria-label="'选择授课 '+o.name+' '+o.id+'班'"></td><td><b>{{o.name}}</b><small class="subline">{{o.code}} · {{o.id}} 班</small></td><td>{{time(o)}}</td><td>{{o.professor}}</td><td>{{o.enrolled}} / 10</td></tr></tbody></table></div><div v-if="!teaching.eligible.length" class="empty"><p>暂无可授课课程，请联系教务管理员配置授课资格。</p></div></section></template>

    <template v-if="tab==='roster'"><section class="panel"><div class="section-heading"><div><h2>学生名单与成绩录入</h2><p class="muted">本学期可查看名单，已结束学期可录入或修改成绩。</p></div><select aria-label="选择授课班级" @change="getRoster(Number($event.target.value))"><option value="">请选择教学班</option><option v-for="o in teaching.mine" :value="o.id" :key="o.id">{{o.term_id===overview.term.id?'本学期':'上学期'}} · {{o.name}} · {{o.id}} 班</option></select></div><template v-if="roster"><div class="table-scroll"><table><thead><tr><th>学生账号</th><th>姓名</th><th>成绩</th></tr></thead><tbody><tr v-for="s in roster.students" :key="s.id"><td class="mono">{{s.username}}</td><td>{{s.name}}</td><td><select v-if="roster.can_grade" v-model="s.grade" :aria-label="s.name+'的成绩'"><option value="">留空 / 暂不录入</option><option v-for="grade in ['A','B','C','D','F','I']" :value="grade">{{grade}}</option></select><span v-else>{{s.grade||'本学期暂不录入'}}</span></td></tr></tbody></table></div><div v-if="!roster.students.length" class="empty"><p>暂无学生选修此班级。</p></div><div class="panel-footer" v-if="roster.can_grade"><small class="muted">留空不覆盖已有成绩。</small><button class="button primary" :disabled="busy||!roster.students.length" @click="saveGrades">保存成绩</button></div></template><div v-else class="empty"><Users :size="40"/><h3>选择一个教学班</h3></div></section></template>

    <template v-if="tab==='users'"><div class="toolbar"><label class="search"><Search :size="18"/><input v-model="query" placeholder="搜索姓名或账号" aria-label="搜索师生"></label><button class="button primary" @click="editUser()"><Plus :size="16"/>添加人员</button></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>姓名 / 账号</th><th>身份</th><th>院系</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in filteredUsers" :key="u.id"><td><b>{{u.name}}</b><small class="subline mono">{{u.username}}</small></td><td>{{roleNames[u.role]}}</td><td>{{u.department}}</td><td><span :class="['badge',u.status==='active'?'green':'gray']">{{u.status==='active'?'正常':'停用'}}</span></td><td><div class="inline-actions"><button @click="editUser(u)">编辑</button><button v-if="u.role==='professor'" @click="editEligibility(u)">授课资格</button><button class="danger-text" @click="deleteUser(u)">删除</button></div></td></tr></tbody></table></div><div v-if="!filteredUsers.length" class="empty"><p>没有找到匹配的人员。</p></div></section></template>

    <template v-if="tab==='registration'"><section class="panel registration-panel"><span :class="['badge',termOpen?'green':'gray']">{{termOpen?'选课进行中':'选课已关闭'}}</span><h2>{{overview.term.name}}</h2><ol class="process-list"><li><b>检查授课安排</b><p>取消没有任课教师的教学班。</p></li><li><b>尝试备选补位</b><p>对未满 4 门的已提交课表按备选顺序补位，并检查名额、先修课及时间冲突。</p></li><li><b>确认开班及计费</b><p>取消最终不足 3 人的教学班，按保留课程生成计费通知；外部服务故障时自动重试。</p></li></ol><div class="alert neutral">关闭选课会结束学生退改选及教师授课调整。系统不提供本学期重新开放入口。</div><button class="button primary" :disabled="!termOpen||busy" @click="closeRegistration">{{termOpen?'关闭本学期选课':'本学期已关闭'}}</button></section></template>

    <template v-if="tab==='invoices'"><section class="panel"><div class="section-heading"><div><h2>学费计费通知</h2><p class="muted">关闭选课后生成，发送失败自动重试。</p></div><span class="badge gray">{{invoices.length}} 条记录</span></div><div class="table-scroll"><table><thead><tr><th>编号</th><th>学生</th><th>课程数</th><th>发送状态</th><th>尝试次数</th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id"><td class="mono">INV-{{String(i.id).padStart(4,'0')}}</td><td>{{i.student}}</td><td>{{i.courses.length}}</td><td><span :class="['badge',i.status==='sent'?'green':'amber']">{{statuses[i.status]}}</span><small v-if="i.last_error" class="subline">{{i.last_error}}</small></td><td>{{i.attempts}}</td></tr></tbody></table></div><div v-if="!invoices.length" class="empty"><CreditCard :size="40"/><h3>还没有计费记录</h3><p>关闭本学期选课后，将按学生最终课表生成计费通知。</p></div></section></template>

    <template v-if="tab==='audit'"><section class="panel"><div class="section-heading"><h2>最近操作记录</h2><span class="muted small">最多展示 100 条</span></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>详情</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td>{{new Date(e.created_at).toLocaleString('zh-CN')}}</td><td>{{e.actor}}</td><td class="mono">{{e.action}}</td><td class="mono small">{{e.detail}}</td></tr></tbody></table></div><div v-if="!events.length" class="empty"><p>暂无操作记录。</p></div></section></template>

    <template v-if="tab==='integrations'"><section class="panel integration-panel"><h2>外部系统联调</h2><p class="muted">这里连接的是课程设计模拟服务，用于演示外部故障及恢复行为。</p><label class="integration-row"><span><b>旧课程目录服务</b><small>只读访问，服务不可用时课程目录显示错误提示。</small></span><input type="checkbox" v-model="integrations.catalog_available" aria-label="课程目录服务可用"></label><label class="integration-row"><span><b>计费服务</b><small>不可用期间保留通知，恢复后自动重试并去重。</small></span><input type="checkbox" v-model="integrations.billing_available" aria-label="计费服务可用"></label><p class="footnote">计费服务已接收 {{integrations.receipts||0}} 条唯一通知。勾选表示服务可用。</p><button class="button primary" :disabled="busy" @click="saveIntegrations">保存模拟服务状态</button></section></template>
    
   </main>
  </div>
  <div v-if="userForm" class="modal-backdrop" @click.self="userForm=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="user-modal-title"><div class="section-heading"><h2 id="user-modal-title">{{userForm.id?'编辑人员':'添加人员'}}</h2><button @click="userForm=null" aria-label="关闭编辑"><X/></button></div><form @submit.prevent="saveUser"><div class="form-grid"><label>姓名<input v-model="userForm.name" required maxlength="80"></label><label>账号<input v-model="userForm.username" :disabled="!!userForm.id" required minlength="3" maxlength="50"></label><label>身份<select v-model="userForm.role" :disabled="!!userForm.id"><option value="student">学生</option><option value="professor">教师</option></select></label><label>状态<select v-model="userForm.status"><option value="active">正常</option><option value="inactive">停用</option></select></label><label>院系<input v-model="userForm.department" required maxlength="80"></label><label>{{userForm.id?'新密码（不修改请留空）':'初始密码'}}<input v-model="userForm.password" type="password" :required="!userForm.id" minlength="8" autocomplete="new-password"></label><label>出生日期<input v-model="userForm.birth_date" type="date"></label><label>毕业日期<input v-model="userForm.graduation_date" type="date"></label><label class="wide">身份识别号<input v-model="userForm.identity_number" maxlength="30" placeholder="演示请使用虚构信息"></label></div><div v-if="error" class="alert error" role="alert">{{error}}</div><div class="panel-footer"><button type="button" class="button secondary" @click="userForm=null">取消</button><button class="button primary" :disabled="busy">保存信息</button></div></form></section></div>
  <div v-if="eligibilityUser" class="modal-backdrop" @click.self="eligibilityUser=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="eligibility-title"><div class="section-heading"><h2 id="eligibility-title">{{eligibilityUser.name}} · 授课资格</h2><button @click="eligibilityUser=null" aria-label="关闭授课资格"><X/></button></div><label v-for="c in uniqueCourses" :key="c.course_id" class="eligibility-option"><input type="checkbox" :value="c.course_id" v-model="eligibilityIds">{{c.code}} · {{c.name}}</label><div v-if="error" class="alert error">{{error}}</div><div class="panel-footer"><button class="button secondary" @click="eligibilityUser=null">取消</button><button class="button primary" :disabled="busy||!termOpen" @click="saveEligibility">保存授课资格</button></div></section></div>
  <div v-if="confirmBox" class="modal-backdrop"><section class="modal confirm-modal" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><AlertCircle class="green-text" :size="30"/><h2 id="confirm-title">{{confirmBox.title}}</h2><p>{{confirmBox.description}}</p><div class="panel-footer"><button class="button secondary" @click="confirmBox=null">取消</button><button class="button primary" :disabled="busy" @click="doConfirm">确认操作</button></div></section></div>
 </div>
</template>
